function renderSoundHistory(){const list=$('soundHistory');list.replaceChildren();for(const e of soundEntries.slice(0,12)){const li=document.createElement('li'),label=document.createElement('strong'),small=document.createElement('small'),p=document.createElement('p');label.textContent=e.title;small.textContent=new Date(e.utc).toLocaleTimeString()+' · '+(e.source==='speech'?'Яриа таних үйлчилгээ':e.source==='local'?'Whisper · төхөөрөмж дээр':'Сигналын дүрмийн тайлбар');p.textContent=e.detail;li.append(label,small,p);if(e.role!=='unmarked'){const mark=document.createElement('p');mark.className='speech-mark';mark.textContent=e.role==='question'?'◎ Миний хэлсэн үг / асуулт · хэрэглэгч тэмдэглэсэн':'↳ Хариу гэж тэмдэглэсэн · «'+e.questionText+'» · эх үүсвэр/утга баталгаагүй';li.append(mark)}if(['speech','local'].includes(e.source)){const controls=document.createElement('div');controls.className='utterance-actions';for(const [kind,text]of [['question','Миний хэлсэн үг / асуулт'],['reply','Хариу гэж тэмдэглэх']]){const button=document.createElement('button');button.textContent=text;button.disabled=state.demo||(kind==='reply'&&(!activeQuestion||e.sequence<=activeQuestion.sequence));button.onclick=()=>annotateSpeech(e,kind);controls.append(button)}li.append(controls)}list.append(li)}$('questionStatus').textContent=activeQuestion?'Тэмдэглэсэн асуулт: «'+activeQuestion.title+'»':'Асуулт тэмдэглээгүй.';$('clearQuestion').disabled=!activeQuestion}
