setInterval(()=>{const active=!!state.analyser&&!state.demo;$('speechToggle').disabled=state.demo;$('soundStatus').textContent=state.demo?'ДЕМО · БОДИТ ДУУ ТАНИХГҮЙ':active?'LIVE · СИГНАЛЫН ТАЙЛБАР':'МИКРОФОН УНТРААЛТТАЙ';if(!active){if(wasAnalysing)soundDetector=new SoundEvents();wasAnalysing=false;return}wasAnalysing=true;const data=new Float32Array(state.analyser.fftSize),spectrum=new Float32Array(state.analyser.frequencyBinCount);state.analyser.getFloatTimeDomainData(data);state.analyser.getFloatFrequencyData(spectrum);const e=soundDetector.update(dbfs(data),performance.now(),concentratedSpectrum(spectrum));if(!e)return;$('soundTitle').textContent=e.title;$('soundMeaning').textContent=e.possible;$('soundEvidence').textContent=`${Math.round(e.duration)} мс · оргил ${e.peak.toFixed(1)} dBFS · Ангилалт баталгаагүй, дүрэмд суурилсан`;soundEntry(e.title,e.possible+' '+Math.round(e.duration)+' мс, '+e.peak.toFixed(1)+' dBFS','signal')},50);
