const local={worker:null,ready:false,phase:'idle',stream:null,recorder:null,timer:null,recordTimer:null,token:0,id:0,cancelled:false,chunks:[],started:0,clip:null,clipUrl:null};
function localButtons(){const active=local.phase!=='idle';$('localLoad').disabled=active||local.ready||state.demo;$('localRecord').disabled=state.demo||(!local.ready&&local.phase!=='recording')||(active&&local.phase!=='recording');$('localRecord').textContent=local.phase==='recording'?'■ Зогсоож текст болгох':'● 15 секунд ярих';$('localCancel').disabled=!active;$('speechToggle').disabled=active||state.demo}
function cancelLocal(){if(local.phase==='idle')return;local.cancelled=true;local.token++;clearTimeout(local.timer);clearInterval(local.recordTimer);local.stream?.getTracks().forEach(t=>t.stop());local.stream=null;if(local.recorder?.state==='recording'){local.recorder.onstop=null;try{local.recorder.stop()}catch{}}local.recorder=null;if(['loading','processing'].includes(local.phase)){local.worker?.terminate();local.worker=null;local.ready=false}local.phase='idle';local.chunks=[];$('localStatus').textContent='Цуцлагдсан. Бичлэг зогссон.';localButtons()}
