$('localCancel').onclick=cancelLocal;setInterval(localButtons,300);

function showLocalClip(blob){if(local.clipUrl)URL.revokeObjectURL(local.clipUrl);local.clip=blob;local.clipUrl=URL.createObjectURL(blob);$('localPlayback').src=local.clipUrl;$('localClip').hidden=false;}
$('localDownload').onclick=()=>{if(local.clip)download(local.clip,'ghost-lens-speech-'+Date.now()+'.'+(local.clip.type.includes('mp4')?'m4a':local.clip.type.includes('ogg')?'ogg':'webm'))};

function deviceDiagnostics(){let embedded=true;try{embedded=window.self!==window.top}catch{}return {version:9,secure:window.isSecureContext,embedded,mediaDevices:!!navigator.mediaDevices?.getUserMedia,motionAPI:!!window.DeviceMotionEvent,motionPermissionAPI:typeof window.DeviceMotionEvent?.requestPermission==='function',magnetometerAPI:'Magnetometer' in window,policy:Object.fromEntries(['camera','microphone','accelerometer','gyroscope','magnetometer'].map(f=>[f,policyState(f)])),cameraError:state.cameraErrorInfo||null,cameraLive:!!state.camera,motionStatus:$('motionStatus').textContent,magneticStatus:$('magStatus').textContent,browser:navigator.userAgent};}
function renderDeviceDiagnostics(){const d=deviceDiagnostics();$('deviceDiagnostics').textContent=JSON.stringify(d,null,2);$('deviceContext').textContent=d.embedded?'Браузерын доторх хүрээнд нээгдсэн. Камер/хөдөлгөөн хаагдаж болно; шууд холбоосыг тусдаа браузерт нээнэ үү.':'Браузерын шууд хуудас · '+(d.secure?'HTTPS':'HTTPS биш');}
